export const scenarioList = Object.entries(scenarios).map(([key, s]) => ({ key, label: s.label }));

function current(): { status: Json; key: string } {
  const key = new URLSearchParams(location.search).get("s") ?? "live";
  const s = scenarios[key] ?? scenarios.live;
  return { key, status: { ...base, ...s.status } };
}

const ready = (data: unknown) => ({ state: "ready", data });

/** The answer to one command, or {__reject: sentence} for a refusal. */
export function answer(cmd: string, args: Record<string, unknown>): unknown {
  const { status } = current();
  const running = status.running === true;
  const stoppedAsk = { state: "stopped" };
  const phase = status.phase as { phase: string; height?: number };
  switch (cmd) {
    case "get_node_status":
      return status;
    case "ask_chain_progress":
      if (!running) return stoppedAsk;
      return ready({
        height: phase.height ?? 0,
        headers: TIP,
        progress: 0.9999,
        near_tip: (phase.height ?? 0) >= TIP - 10,
        peers: 12,
      });
    case "ask_supply":
      return running ? ready({ mined_btx: 4_886_664, cap_btx: 21_000_000, pct: 0.2327, height: phase.height ?? TIP }) : stoppedAsk;
    case "ask_next_halving":
      return running
        ? ready({ blocks_remaining: 104_240, at_height: 350_000, est_secs: 104_240 * 90, from_reward_btx: 20, to_reward_btx: 10, height: TIP })
        : stoppedAsk;
    case "ask_fees":
      return running ? ready({ feerate_btx_kvb: null, mempool_txs: 3, mempool_vsize: 1180 }) : stoppedAsk;
    case "ask_mining":
      return running ? ready({ difficulty: 1834.27, network_hashps: 2_430_000, height: TIP }) : stoppedAsk;
    case "ask_block":
      if (!running) return stoppedAsk;
      if (args.query && !/^\d+$|^[0-9a-f]{64}$/i.test(String(args.query).replace(/,/g, "").trim())) {
        return { state: "unavailable", data: { message: "Type a block height or a 64-character block hash." } };
      }
      return ready({
        height: TIP,
        hash: "0d20af508b6edccb6f47a0a91d12fa2ed3d44ed8b2105cfc340c7fee8730bf22",
        time: Math.floor(now / 1000) - 70,
        n_tx: 2,
        size: 1450,
      });
    case "ask_transaction":
      return running ? ready({ kind: "needs_index" }) : stoppedAsk;
    case "tools_restart_check":
      return running ? null : "Start the node first.";
    case "tools_fast_forward_status":
      return { running: false, message: null };
    case "tools_fast_forward_check":
      return { kind: "none" };
    case "tools_engine_notices":
      return running ? ready([]) : stoppedAsk;
    case "tools_diagnostics":
      return "easyNode 0.7.11 diagnostics (preview)\nStatus: " + String(args.statusLine ?? "");
    case "tools_console_run":
      return { kind: "output", text: '{\n  "blocks": 245760\n}' };
    case "wallet_status":
      return running
        ? ready({
            enabled: true,
            imported: false,
            address: null,
            trusted: 0,
            pending: 0,
            immature: 0,
            backfilling: false,
            tip_stale: status.tip_stale === true,
            blocks_behind: 0,
            txs: [],
          })
        : stoppedAsk;
    case "esplora_preflight":
      return { allowed: true, blocker: null, warnings: [], electrs_found: null, caddy_found: null, listen: "http://127.0.0.1:3080" };
    case "node_footprint":
      return { running, cpu_pct: running ? 3.4 : null, mem_mb: running ? 612 : 0, chain_mb: 9.8 * 1024 };
    case "open_global_stats":
    case "open_data_folder":
    case "mark_welcome_shown":
    case "record_update_check":
    case "forget_failed_update":
    case "remember_failed_update":
    case "close_choice":
      return null;
    case "peek_update_refusal":
      return null;
    case "set_node_nickname":
      return String(args.name ?? "");
    default:
      if (cmd.startsWith("set_")) return "Saved. It applies the next time the node starts.";
      console.warn("[preview] no answer for", cmd, args);
      return null;
  }
}
